// Determine which tests should run now
const now = new Date();
const currentHour = now.getHours();
const currentDay = now.getDay(); // 0 = Sunday, 6 = Saturday
const currentDate = now.toISOString().split('T')[0];

const testSuites = $json.testSuites;
const testsToRun = [];
const skippedTests = [];

// Check each test suite against its schedule
Object.keys(testSuites).forEach(suiteKey => {
  const suite = testSuites[suiteKey];

  if (!suite.enabled) {
    skippedTests.push({
      suite: suiteKey,
      reason: 'disabled',
      nextCheck: 'next_schedule'
    });
    return;
  }

  let shouldRun = false;

  // Daily schedules
  if (suite.schedule === 'daily') {
    const [scheduledHour, scheduledMinute] = suite.time.split(':').map(Number);
    const scheduledTime = new Date();
    scheduledTime.setHours(scheduledHour, scheduledMinute, 0, 0);

    // Check if we're within the scheduled hour and haven't run today
    const timeDiff = now - scheduledTime;
    const hoursDiff = timeDiff / (1000 * 60 * 60);

    if (hoursDiff >= 0 && hoursDiff < 1) {
      // Check if already run today
      const lastRunToday = suite.lastRun && suite.lastRun.startsWith(currentDate);
      if (!lastRunToday) {
        shouldRun = true;
      }
    }
  }

  // Weekly schedules
  else if (suite.schedule === 'weekly') {
    const dayMap = { 'sunday': 0, 'monday': 1, 'tuesday': 2, 'wednesday': 3, 'thursday': 4, 'friday': 5, 'saturday': 6 };
    const scheduledDay = dayMap[suite.day];

    if (currentDay === scheduledDay) {
      const [scheduledHour, scheduledMinute] = suite.time.split(':').map(Number);
      const scheduledTime = new Date();
      scheduledTime.setHours(scheduledHour, scheduledMinute, 0, 0);

      const timeDiff = now - scheduledTime;
      const hoursDiff = timeDiff / (1000 * 60 * 60);

      if (hoursDiff >= 0 && hoursDiff < 1) {
        const lastRunToday = suite.lastRun && suite.lastRun.startsWith(currentDate);
        if (!lastRunToday) {
          shouldRun = true;
        }
      }
    }
  }

  // Bi-weekly schedules
  else if (suite.schedule === 'bi_weekly') {
    // Simplified: run every other Friday
    const dayMap = { 'sunday': 0, 'monday': 1, 'tuesday': 2, 'wednesday': 3, 'thursday': 4, 'friday': 5, 'saturday': 6 };
    const scheduledDay = dayMap[suite.day];

    if (currentDay === scheduledDay) {
      const weekNumber = Math.ceil((now.getDate() - 1) / 7) + 1;

      // Run on odd weeks (1st, 3rd, 5th Friday of the month)
      if (weekNumber % 2 === 1) {
        const [scheduledHour, scheduledMinute] = suite.time.split(':').map(Number);
        const scheduledTime = new Date();
        scheduledTime.setHours(scheduledHour, scheduledMinute, 0, 0);

        const timeDiff = now - scheduledTime;
        const hoursDiff = timeDiff / (1000 * 60 * 60);

        if (hoursDiff >= 0 && hoursDiff < 1) {
          const lastRunToday = suite.lastRun && suite.lastRun.startsWith(currentDate);
          if (!lastRunToday) {
            shouldRun = true;
          }
        }
      }
    }
  }

  if (shouldRun) {
    testsToRun.push({
      suite: suiteKey,
      name: suite.name,
      priority: suite.priority,
      estimatedDuration: suite.duration,
      scheduledTime: now.toISOString()
    });
  } else {
    skippedTests.push({
      suite: suiteKey,
      reason: 'not_scheduled_time',
      nextRun: suite.nextRun || 'next_schedule'
    });
  }
});

// Sort by priority
const priorityOrder = { 'critical': 1, 'high': 2, 'medium': 3, 'low': 4 };
testsToRun.sort((a, b) => priorityOrder[a.priority] - priorityOrder[b.priority]);

return [{
  json: {
    sessionId: $json.sessionId,
    timestamp: now.toISOString(),
    testsToRun,
    skippedTests,
    schedulingDecision: {
      totalSuites: Object.keys(testSuites).length,
      testsScheduled: testsToRun.length,
      testsSkipped: skippedTests.length
    }
  }
}];

// Generate dashboard summary and insights
const recentExecutions = $json.recentExecutions || [];
const scheduledTests = $input.item(2).json.testsToRun || [];
const skippedTests = $input.item(2).json.skippedTests || [];

// Calculate execution statistics
const totalExecutions = recentExecutions.length;
const successfulExecutions = recentExecutions.filter(e => e.status === 'passed').length;
const failedExecutions = recentExecutions.filter(e => e.status === 'failed').length;
const runningExecutions = recentExecutions.filter(e => e.status === 'running').length;

const successRate = totalExecutions > 0 ? (successfulExecutions / totalExecutions * 100).toFixed(1) : 0;

// Calculate average execution time
const completedExecutions = recentExecutions.filter(e => e.duration && e.duration > 0);
const avgExecutionTime = completedExecutions.length > 0 ? 
  completedExecutions.reduce((sum, e) => sum + e.duration, 0) / completedExecutions.length : 0;

// Test suite performance
const suitePerformance = {};
recentExecutions.forEach(execution => {
  if (!suitePerformance[execution.suite]) {
    suitePerformance[execution.suite] = {
      total: 0,
      passed: 0,
      failed: 0,
      avgDuration: 0,
      lastRun: null
    };
  }

  suitePerformance[execution.suite].total++;
  if (execution.status === 'passed') suitePerformance[execution.suite].passed++;
  if (execution.status === 'failed') suitePerformance[execution.suite].failed++;
  if (execution.duration) {
    suitePerformance[execution.suite].avgDuration += execution.duration;
  }
  if (!suitePerformance[execution.suite].lastRun || 
      new Date(execution.timestamp) > new Date(suitePerformance[execution.suite].lastRun)) {
    suitePerformance[execution.suite].lastRun = execution.timestamp;
  }
});

// Calculate averages
Object.keys(suitePerformance).forEach(suite => {
  const completed = recentExecutions.filter(e => e.suite === suite && e.duration);
  if (completed.length > 0) {
    suitePerformance[suite].avgDuration = 
      suitePerformance[suite].avgDuration / completed.length;
  }
  suitePerformance[suite].successRate = 
    suitePerformance[suite].total > 0 ? 
    (suitePerformance[suite].passed / suitePerformance[suite].total * 100).toFixed(1) : 0;
});

// Generate insights
const insights = [];

if (successRate < 85) {
  insights.push({
    type: 'concern',
    message: `Test success rate (${successRate}%) is below target (85%)`,
    priority: 'high'
  });
}

if (failedExecutions > successfulExecutions) {
  insights.push({
    type: 'alert',
    message: 'More tests are failing than passing',
    priority: 'critical'
  });
}

if (avgExecutionTime > 60) {
  insights.push({
    type: 'performance',
    message: `Average test execution time (${avgExecutionTime.toFixed(1)}s) is high`,
    priority: 'medium'
  });
}

// Check for consistently failing suites
Object.keys(suitePerformance).forEach(suite => {
  if (suitePerformance[suite].successRate < 70 && suitePerformance[suite].total >= 3) {
    insights.push({
      type: 'suite_issue',
      message: `${suite} test suite has low success rate (${suitePerformance[suite].successRate}%)`,
      priority: 'high',
      suite: suite
    });
  }
});

// Scheduling insights
if (scheduledTests.length > 0) {
  insights.push({
    type: 'schedule',
    message: `${scheduledTests.length} test suite(s) scheduled for execution`,
    priority: 'info'
  });
}

return [{
  json: {
    sessionId: $input.item(2).json.sessionId,
    timestamp: new Date().toISOString(),
    executionStats: {
      total: totalExecutions,
      successful: successfulExecutions,
      failed: failedExecutions,
      running: runningExecutions,
      successRate: parseFloat(successRate),
      avgExecutionTime
    },
    suitePerformance,
    currentSchedule: {
      scheduled: scheduledTests.length,
      skipped: skippedTests.length,
      nextRuns: this._calculateNextRuns($input.item(2).json.testSuites)
    },
    insights,
    summary: {
      overallHealth: successRate >= 85 ? 'healthy' : successRate >= 70 ? 'warning' : 'critical',
      totalInsights: insights.length,
      criticalIssues: insights.filter(i => i.priority === 'critical').length,
      highPriorityIssues: insights.filter(i => i.priority === 'high').length
    }
  }
}];
